) AS (
  VALUES 
    (283::BIGINT, 'El profe en general explica bien y es bastante sin filtro a la hora de hablar. Es importante leer todo (hasta las instrucciones) porque es de dejar trampas en las evaluaciones para "enseñar" a leer a las personas. No suponga ninguna instrucción y aproveche las tutorías y pasa fácil.'::TEXT, 4.0::NUMERIC(3,1), 8.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('85','')::SMALLINT, NULL::SMALLINT, ARRAY['Requiere mucha lectura', 'Exámenes retadores']::TEXT[], '2026-07-06T00:00:00+00:00'::TIMESTAMPTZ, 'e92a1ff16bcd80d1bfc2492c3475726d1a0ba3a3fe50f46646129c1a1545e341'::TEXT, ARRAY[2527]::BIGINT[]),
    (283::BIGINT, 'Es buen profe, explica muy bien la materia, se aprende mucho en el curso. Los exámenes siempre con muchas trampas, son de prestar atención, leer detenidamente y pensar lo que va a responder.'::TEXT, 8.0::NUMERIC(3,1), 8.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('80','')::SMALLINT, NULL::SMALLINT, ARRAY['Califica con rigor', 'Deja trabajos largos', 'Exámenes retadores']::TEXT[], '2026-06-30T00:00:00+00:00'::TIMESTAMPTZ, '08951d67b7b0db9ea1d6cb1eaa71d7d465ed6e4fdbda9fd2597ffcee92bd4bc0'::TEXT, ARRAY[2535]::BIGINT[]),
    (283::BIGINT, 'Ninguno'::TEXT, 10.0::NUMERIC(3,1), 2.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('85','')::SMALLINT, NULL::SMALLINT, ARRAY['Califica con rigor', 'Clases largas']::TEXT[], '2026-04-13T00:00:00+00:00'::TIMESTAMPTZ, '9f98464d497997d72066410cb307d33caf3898791cf0ccadbb9c87ef5150e404'::TEXT, ARRAY[2527]::BIGINT[]),
    (283::BIGINT, 'En general es un buen profe, explica muy bien la materia, aunque parece que le gusta asustar al estudiante. Los exámenes llenos de trampas y pueden llegar a ser complicados, son de leer bien y verificar su comprensión de la materia.'::TEXT, 4.0::NUMERIC(3,1), 9.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('70','')::SMALLINT, NULL::SMALLINT, ARRAY['Califica con rigor', 'Deja trabajos largos', 'Exámenes retadores']::TEXT[], '2025-12-11T00:00:00+00:00'::TIMESTAMPTZ, '2877561e64837dcccd48cf65282b720cc1ff55b8f14d8fb594192bee8da4a36b'::TEXT, ARRAY[2527]::BIGINT[]),
    (283::BIGINT, 'Es un profesor excelente. Usted debe estudiar a conciencia y prestar mucha atención en clase. Con lo que explica en clase usted entiende todo para los exámenes. Pero estos tienen mucha trampa, entonces cuidado con esto. TQM'::TEXT, 6.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('80','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2024-08-20T00:00:00+00:00'::TIMESTAMPTZ, 'cc3d8b4f64d994a3886a40984c217bd69e695b0e232b8bdc6980db904875d420'::TEXT, ARRAY[2535]::BIGINT[]),
    (283::BIGINT, 'Amo que de los cursos asincrónicos se pasa súper fácil.'::TEXT, 10.0::NUMERIC(3,1), 8.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('95','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2024-06-19T00:00:00+00:00'::TIMESTAMPTZ, '46b6fc79e97c905f3ab9c4f6d497765f5b5a71db8bcbf68bb10e72211f244e0b'::TEXT, ARRAY[2588]::BIGINT[]),
    (283::BIGINT, 'Lo lleve en verano, medio pesado después del primer examen, pero bien, como siempre con trampas en los exámenes, explica súpero bien'::TEXT, 6.0::NUMERIC(3,1), 8.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('90','')::SMALLINT, NULL::SMALLINT, ARRAY['Califica con rigor', 'Exámenes retadores', 'Tomaría su clase nuevamente']::TEXT[], '2024-01-27T00:00:00+00:00'::TIMESTAMPTZ, 'cba4b8382c55bdc1eeeb0bb75d4a87b99122e762c83e0a37228b3d8896e8d159'::TEXT, ARRAY[2571]::BIGINT[]),
    (283::BIGINT, 'El curso es fácil? Sí. Solo ponga atención mae, eso es todo. Si usted se mete en la vara (tanto para diseño como para otros cursos) va a pasar fácilmente. ANALICE LO QUE VA A DECIR ANTES DE DECIRLO. Él pone muchas trampas, pero es para que usted aprenda. En serio vale la pena, ayuda en todo :)'::TEXT, 6.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY['Califica con rigor', 'Brinda apoyo']::TEXT[], '2023-06-21T00:00:00+00:00'::TIMESTAMPTZ, '813ab7bca7c12b9069b170f481deb1dcae88767ca259dc9ac7da7a077b403696'::TEXT, ARRAY[2535]::BIGINT[]),
    (283::BIGINT, 'Es excelente dando la materia, se le entiende normalmente todo lo que explica, se preocupa de que todos entendamos la materia, en exámenes es muy difícil, suele meter trampas y son largos y de justificar todo'::TEXT, 4.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('70','')::SMALLINT, NULL::SMALLINT, ARRAY['Califica con rigor', 'La participación importa', 'Asistencia obligatoria']::TEXT[], '2023-06-21T00:00:00+00:00'::TIMESTAMPTZ, 'cb1270f57731b036e8599d54fc847cc32cf64014b2a99fdc59f4c697c650bc54'::TEXT, ARRAY[2535]::BIGINT[]),
    (283::BIGINT, 'El profe dando clases es como un Dios, excelente, PERO a como explica de bien así de duros son los exámenes, los proyectos son largos e igual que las tareas, hay que sentarse desde que deja algo. No da mucho tiempo de más si lo pides'::TEXT, 4.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('70','')::SMALLINT, NULL::SMALLINT, ARRAY['Califica con rigor', 'Deja trabajos largos', 'Exámenes retadores']::TEXT[], '2023-03-03T00:00:00+00:00'::TIMESTAMPTZ, '47c0fdfb045b0f97cc8dd3a9abab50b262b01d44df48c00086905e71d2508027'::TEXT, ARRAY[2535]::BIGINT[]),
    (283::BIGINT, 'Excelente profesor. Explica detenidamente, a veces mas bien es deemasiado lento, pero es mejor eso! Los proyectos son complicados, empiezelos desde el día 1. Se nota que le gusta lo que enseña y lo hace todo muy ameno. 100% recomendado'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('90','')::SMALLINT, NULL::SMALLINT, ARRAY['Muchas tareas', 'Deja trabajos largos']::TEXT[], '2022-06-22T00:00:00+00:00'::TIMESTAMPTZ, '4a3e5136c82d3d81fb8303b5887a823b3066901cbfcd8af9e2afcd72eb0ed346'::TEXT, ARRAY[2535]::BIGINT[]),
    (283::BIGINT, 'El profe explica excelente, se preocupa porque los estudiantes entiendan. El asistente es que revisa todo y dura un mundo en revisar tareas/ proyectos. Los exámenes están llenos de trampas, son largos. Los proyectos son grandes. El curso necesita que se le dedique mucho tiempo'::TEXT, 4.0::NUMERIC(3,1), 8.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY['Muchas tareas', 'Requiere mucha lectura', 'Exámenes retadores']::TEXT[], '2022-06-15T00:00:00+00:00'::TIMESTAMPTZ, '46de471f8c35acca904c5a22438369731bbda5cd07d4789795a44f80bedb58f8'::TEXT, ARRAY[2535]::BIGINT[]),
    (283::BIGINT, 'Redunda en exceso. Explica muy bien y se aprende demasiado. Es un curso exigente, las clases asincrónicas requieren mucho tiempo. Solo usa la basura de Facebook para comunicarse. A veces, es medio payaso, le fascina hacer todo un show y meter miedo.'::TEXT, 6.0::NUMERIC(3,1), 9.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('80','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2022-06-07T00:00:00+00:00'::TIMESTAMPTZ, 'cb16c3d6cd8ee576c5b27839a1f192afb9bd0f32b2805c616495e9a5aae0b025'::TEXT, ARRAY[2535]::BIGINT[]),
    (283::BIGINT, 'Excelente profesor. Se nota que le gusta lo que hace porque explica de forma muy clara y le aclara la duda de manera concisa, de forma que no se le va a olvidar la respuesta a esa duda. Es un curso difícil por su contenido, pero el profesor lo hace llevadero y disfrutable.'::TEXT, 4.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('80','')::SMALLINT, NULL::SMALLINT, ARRAY['Califica con rigor', 'Da buena retroalimentación', 'Muchas tareas']::TEXT[], '2021-02-10T00:00:00+00:00'::TIMESTAMPTZ, '72afba43277ebb96395c2d76b35458398026fd3faa0fba890fb53b09c4db69a1'::TEXT, ARRAY[2535]::BIGINT[]),
    (283::BIGINT, 'Es excelente profe, de verdad explica super detallado y es muy dulce. Hay que prestar bastante atención y le gusta que en clases virtuales uno participe bastante. En los exámenes hay muchas trampas en las progras hay que ponerle mucho cuidado a la docu, el curso es de dedicarle tiempo.'::TEXT, 4.0::NUMERIC(3,1), 9.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('70','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2021-01-28T00:00:00+00:00'::TIMESTAMPTZ, '38b460ef9d1d14a572a33925058a8628d0c9725e27e2fdc7b0f4c17344b9f54d'::TEXT, ARRAY[2535]::BIGINT[]),
    (283::BIGINT, 'Me atrevería a decir que el mejor profe de la carrera de ATI. Explica excelente y el asistente Andy es un crack también, son un complemento muy bueno. Si querés pasar bien bien tenés que ir a las tutorías. Los exámenes son durísimos pero hay que prestar atención al detalle.'::TEXT, 4.0::NUMERIC(3,1), 9.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2020-11-16T00:00:00+00:00'::TIMESTAMPTZ, '0364f0792a4d9fb5c89a038419803f9144d1b05329059346e3a791e477cec16b'::TEXT, ARRAY[2535]::BIGINT[]),
    (283::BIGINT, 'De los mejores profesores que he tenido. Explica super bien y hace interesante el curso. Hay que estudiar bastante para los exámenes porque requieren mucho análisis.'::TEXT, 4.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY['Muchas tareas', 'Respetado por los estudiantes', 'Tomaría su clase nuevamente']::TEXT[], '2020-09-03T00:00:00+00:00'::TIMESTAMPTZ, '3cc30330db797a2ced800f8b446c001222307e03fba837ba2f41f37aa72825eb'::TEXT, ARRAY[2535]::BIGINT[]),
    (283::BIGINT, 'Es de los mejores profesores explicando. Uno aprende bastante y explica muy bien. Resuelve las dudas que uno tenga. Deja muchas tareas, pero no son tan largas. Para los exámenes se debe estudiar bastante y son de análisis, eso es lo más rudo del curso.'::TEXT, 6.0::NUMERIC(3,1), 9.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('85','')::SMALLINT, NULL::SMALLINT, ARRAY['Da buena retroalimentación', 'Respetado por los estudiantes', 'Inspirador']::TEXT[], '2020-08-24T00:00:00+00:00'::TIMESTAMPTZ, '883ad26f8ddc0cef981bffbc859f60b7d71b43a203a2c8a2431341a4ae1183da'::TEXT, ARRAY[2535]::BIGINT[]),
    (283::BIGINT, 'Diseño es de los mas complicados en la carrera, el profe es buena persona y siempre explica tan bien que prácticamente no hay que preguntarle nada, los exámenes son realmente difíciles con preguntas en los que el que no sabe responder perdió los puntos, estudie mucho(mucho realmente) y pasa'::TEXT, 4.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('70','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2019-02-28T00:00:00+00:00'::TIMESTAMPTZ, 'af0a70f34b36df180e646da93a63c0702be314295770e8e3a80ece775dbf7603'::TEXT, ARRAY[2535]::BIGINT[]),
    (283::BIGINT, 'Los exámenes duros realmente el que sabe y el que no sabe lo pierde ya que siempre pone cascaras de banano para que uno se equivoque hay muchos casos que la gente estaba quedado y mágicamente tenia aprobado el curso. No hay mas opciones de profes que den el curso porque es el coordinador'::TEXT, 4.0::NUMERIC(3,1), 5.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('55','')::SMALLINT, NULL::SMALLINT, ARRAY['Califica con rigor', 'Exámenes retadores']::TEXT[], '2018-10-28T00:00:00+00:00'::TIMESTAMPTZ, '732f9f5462328d723fcd4066560d38cec9f49a7b88c2deabd9f5d284931b791a'::TEXT, ARRAY[2535]::BIGINT[]),
    (283::BIGINT, 'Le encanta poner trampas para que el estudiante pierda puntos. Se llega al punto donde uno prefiere no dar su opinión para evitar comentarios sarcásticos o burlistas si su opinión esta equivocada...'::TEXT, 4.0::NUMERIC(3,1), 5.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('55','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2018-05-05T00:00:00+00:00'::TIMESTAMPTZ, '8fac2e7f3ab3592ce69ee6c8bd7c3d6ffdb416b3d9f8c1dc7534c3f2d00a799a'::TEXT, ARRAY[2535]::BIGINT[]),
    (283::BIGINT, 'Caigale bien y al asistente, si tiene un 60 lo pasa. Queda debiendo'::TEXT, 4.0::NUMERIC(3,1), 6.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2018-02-12T00:00:00+00:00'::TIMESTAMPTZ, 'fcd102f4432b31264c700e81e33b1aae5dfe68710da9ea8715573c4581ba715b'::TEXT, ARRAY[2535]::BIGINT[]),
    (283::BIGINT, 'Excelente profesor, como enseña de bien también le exige a sus alumnos un montón. El siempre se interesa en que el estudiante que pase su curso, realmente este listo para ello. Un curso con Chavarria, se gana con el sudor en la frente y se aprende de verdad.'::TEXT, 4.0::NUMERIC(3,1), 8.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2017-06-27T00:00:00+00:00'::TIMESTAMPTZ, '7aef17973212a05f6630bcf23175d06fb55ee877222cce8187f169d680d1578e'::TEXT, ARRAY[2535]::BIGINT[]),
    (283::BIGINT, 'Se burla de los estudiantes, al inicio del curso pone en ridículo a los estudiantes repitentes, no explica con claridad, da muy poco tiempo para los proyectos'::TEXT, 4.0::NUMERIC(3,1), 4.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY['Califica con rigor', 'Exámenes retadores']::TEXT[], '2017-06-15T00:00:00+00:00'::TIMESTAMPTZ, '14f9e277f8a9ecc5b3fb8d167940e3681a4f3ab7ed9c47de4c900982d02ffbd8'::TEXT, ARRAY[2535]::BIGINT[]),
    (283::BIGINT, 'Explica lo básico, uno se la tiene que jugar para poder hacer las cosas, pasa basureando lo que hacen los estudiantes en vez de explicar que es lo que se hizo mal, no entiendo si fue que cambio este semestre o que, pero una calificación de 9.7 como la que tiene ahorita NO SE LA MERECE'::TEXT, 4.0::NUMERIC(3,1), 5.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('65','')::SMALLINT, NULL::SMALLINT, ARRAY['Califica con rigor', 'Muchas tareas', 'Exámenes retadores']::TEXT[], '2017-02-23T00:00:00+00:00'::TIMESTAMPTZ, 'ea9e7c8c5a7c24b18d775f080cae6dfbc0d7ec2878a30d356b3cadaef08e8f13'::TEXT, ARRAY[2535]::BIGINT[]),
    (283::BIGINT, 'El profe es un crack explicando, los exámenes son brutales, los proyectos con un poco de tiempo e investigación son realizables, para él no existen diagramas de flujo son diagramas de actividad. Se recomienda repasar un poco de POO antes de llevar el curso'::TEXT, 4.0::NUMERIC(3,1), 7.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('80','')::SMALLINT, NULL::SMALLINT, ARRAY['Califica con rigor', 'Muy cómico', 'Muchas tareas']::TEXT[], '2016-11-20T00:00:00+00:00'::TIMESTAMPTZ, 'a64c6b7c849ba115c93c7f4c7c57c559d7134a7944098f2e13fb3f3db32b86d9'::TEXT, ARRAY[2535]::BIGINT[]),
    (283::BIGINT, 'Profesor con gran vocación para enseñar. Deja exámenes con muchas trampas y proyectos sencillos. Se aprende bastante con él y es imposible no entenderle de lo claro que es. Recomendado para este curso.'::TEXT, 6.0::NUMERIC(3,1), 9.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY['Califica con rigor', 'Exámenes retadores', 'Tomaría su clase nuevamente']::TEXT[], '2016-06-23T00:00:00+00:00'::TIMESTAMPTZ, '3d9eec718f95e1cf907409f86e0b138097a9d617eac858dee55a79b7a65b3dd5'::TEXT, ARRAY[2535]::BIGINT[]),
    (283::BIGINT, 'Explica muy muy claro. Es un poco aburrido. Repite un poco lo mismo. Progras realizables. Exámenes un tanto difíciles, y uno simplemente no sabe qué le podría entrar.'::TEXT, 8.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('90','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2016-06-22T00:00:00+00:00'::TIMESTAMPTZ, 'f66634f62ae331c241a2f07ba4ffca47068b45241ec5452708daaa4424086b97'::TEXT, ARRAY[2535]::BIGINT[]),
    (283::BIGINT, 'Muy buen profe, explica muy bien y sabe mucho del tema. Buena persona, muy pura vida! Probablemente es el mejor profe de diseño! Advertencia: pone MUCHAS trampas en los exámenes!!!!!! Los proyectos son fáciles. Da chocolates en los exámenes =D !!!!'::TEXT, 6.0::NUMERIC(3,1), 9.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('85','')::SMALLINT, NULL::SMALLINT, ARRAY['Califica con rigor', 'Da buena retroalimentación', 'Clases excelentes']::TEXT[], '2016-06-08T00:00:00+00:00'::TIMESTAMPTZ, 'bfbe7236a388f9c2074852ebb95d493007761986bb6c84a29a0379d519e4f481'::TEXT, ARRAY[2535]::BIGINT[]),
    (283::BIGINT, 'En las clases se aprende mucho, tiene mucho conocimiento en el tema. Los exámenes son malintencionados (no tiene chance de batear), proyectos algo fáciles.'::TEXT, 4.0::NUMERIC(3,1), 9.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('85','')::SMALLINT, NULL::SMALLINT, ARRAY['Califica con rigor', 'Exámenes retadores']::TEXT[], '2016-06-08T00:00:00+00:00'::TIMESTAMPTZ, '61d7d5c13da7face6f5e5b93258bc5cdc5fcf747868e94775a8c03800c1d14d1'::TEXT, ARRAY[2535]::BIGINT[]),
    (283::BIGINT, 'Repite lo mismo hasta sangrar lo oídos y después califica algunas cosas ni siquiera visto durante el curso. Mucho énfasis sobre el léxico, dejando al lado la evaluación de buenos y malos diseños Ademas, hizo que el asistente revisara los exámenes, lo cual causo problemas!'::TEXT, 4.0::NUMERIC(3,1), 6.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('85','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2016-06-06T00:00:00+00:00'::TIMESTAMPTZ, '60af8450aedbe093d2d18f16dede0a1393e1e496dfe99219e9cafb402374949c'::TEXT, ARRAY[2535]::BIGINT[]),
    (283::BIGINT, 'Es buen profesor, conoce mucho del tema y es claro explicando, pero a veces pasa la raya del respeto a los estudiantes haciendo comentarios groseros cuando alguno hace una pregunta. Las especificaciones de los exámenes no son proporcionales con el tiempo que da para hacerlos. Proyectos fáciles.'::TEXT, 4.0::NUMERIC(3,1), 7.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY['Muchas tareas', 'Clases largas', 'Exámenes retadores']::TEXT[], '2016-06-02T00:00:00+00:00'::TIMESTAMPTZ, 'ae4404d7dbd20447ba1a362bad598959322c77924fd79155de1f06bc60c92394'::TEXT, ARRAY[2535]::BIGINT[]),
    (283::BIGINT, 'Uno de los mejores profesores que dan cursos en la carrera de Ingeniería en Computación (Lástima que esta en ATI). Es un experto en la materia, más en práctica que en la mera teoría}. Es un evangelizador de su area, y sus cursos son los mejores. Lastima que el curso de Diseño sea descuidado por IC.'::TEXT, 6.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2015-10-17T00:00:00+00:00'::TIMESTAMPTZ, 'e5753efdc5cc0d24256953fe8f866d1fc45ce01e89763d442c92cb693694e4f4'::TEXT, ARRAY[2535, 2527]::BIGINT[]),
    (283::BIGINT, 'Es un excelente profesor, le preocupa realmente que el estudiante aprenda. Explica muy claro, los exámenes y trabajos son fáciles si uno realmente se esfuerza. Las clases no son para nada aburridas. Y como persona muy buena gente y respetuoso. PD: Regala chocolates en los exámenes :D'::TEXT, 6.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::BOOLEAN, NULLIF('100','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2015-06-29T00:00:00+00:00'::TIMESTAMPTZ, '6e37a91a884e11a9117d64eb8a61227bd14fa096bf54a4886f9e072685643531'::TEXT, ARRAY[2510, 2512]::BIGINT[]),
    (283::BIGINT, 'Excelente profesor y persona,todo lo explica muy bien claro y realmente le interesa el aprendizaje de los estudiantes. Sin duda lo recomiendo. Siempre prefiere lo explicito y dejar las cosas lo más claras posibles (Y regala chocolates en los examenes :D)'::TEXT, 6.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::BOOLEAN, NULLIF('100','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2015-06-25T00:00:00+00:00'::TIMESTAMPTZ, 'ac4c4d77fc1d73e78d269123b9299e92d2d39b2b9ad007e08eff42294e1c9f56'::TEXT, ARRAY[2510]::BIGINT[]),
    (283::BIGINT, 'Excelente profe, explica super bien la materia, todo queda muy claro y como persona tambien es calidad, a veces anda medio chichoso pero se le pasa se le pasa jaja, super recomendado!!'::TEXT, 6.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::BOOLEAN, NULLIF('100','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2015-06-19T00:00:00+00:00'::TIMESTAMPTZ, '27385db87c314132ada1c92f52951e1b32a5565b858b9ed349b820ba0f82d586'::TEXT, ARRAY[2510, 2512]::BIGINT[]),
    (283::BIGINT, 'Excelente profe, muy recomendado, explica muy bien la materia y ademas es muy buena persona, al principio trata de asustar un poco pero luego se le pasa.'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2015-06-08T00:00:00+00:00'::TIMESTAMPTZ, 'a07193256eb42466b8dd5d067800023fbc098559129c1cfdc9b6e97ac0906f1c'::TEXT, ARRAY[2510, 2512]::BIGINT[]),
    (283::BIGINT, 'Excelente profe, sabe transmitir el mensaje, se preocupa de verdad xq el estudiante aprenda'::TEXT, 8.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::BOOLEAN, NULLIF('95','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2015-05-29T00:00:00+00:00'::TIMESTAMPTZ, '2c8f219a7c17d280387ecf69a04937cf181cdc3e917dc329d19ef9916eac20c3'::TEXT, ARRAY[2535]::BIGINT[]),
    (283::BIGINT, 'RECOMENDADISIMO!'::TEXT, 8.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2015-05-28T00:00:00+00:00'::TIMESTAMPTZ, '18908decf8bad8a71752046d2ca2ed92b308c7b9fda28899976eb3d6dc517292'::TEXT, ARRAY[2510, 2512]::BIGINT[]),
    (283::BIGINT, 'Es un excelente profesor, gracias a el me ayudo a formar las bases que todo programador deberia saber. Lo recomiendo si quieres aprender a programar.'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::BOOLEAN, NULLIF('100','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2014-11-22T00:00:00+00:00'::TIMESTAMPTZ, '1ecd20ec1cbaf6fa33911546bc18180d1a3bb8dcd313568c91ded9c2eab44672'::TEXT, ARRAY[2512]::BIGINT[]),
    (283::BIGINT, 'Excelente como persona y profesor! Tiene vocación para explicar, deja tareas con las que se aprende sobre la materia de verdad. Se preocupa por el estudiante. Para poo es el mejor!'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::BOOLEAN, NULLIF('90','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2014-11-20T00:00:00+00:00'::TIMESTAMPTZ, '38d2683ddcc3e85a1f7f54efbfb221c5fae90a40a21d788a05742ed2a2ba2579'::TEXT, ARRAY[2527]::BIGINT[]),
    (283::BIGINT, 'Excelente profesor, siempre pendiente del aprendizaje de sus alumnos!'::TEXT, 6.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::BOOLEAN, NULLIF('100','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2014-11-18T00:00:00+00:00'::TIMESTAMPTZ, 'f5a59617ad3debcfbaaa294b30cc5ad225d7f36a39e1049dab8ab4e55551ec6f'::TEXT, ARRAY[2510, 2512]::BIGINT[]),
    (283::BIGINT, 'Mejor profe que e tenido.'::TEXT, 8.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::BOOLEAN, NULLIF('100','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2014-11-18T00:00:00+00:00'::TIMESTAMPTZ, '2a786b2a58ec7193421f70b59c930b53c43f8039c5413422ada7e824b1a218f1'::TEXT, ARRAY[2510, 2512]::BIGINT[]),
    (283::BIGINT, 'Excelente profesor, y lo mejor de todo es que tiene experiencia dirigiendo en el mercado laboral, la cual sirve mucho mucho.'::TEXT, 8.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::BOOLEAN, NULLIF('90','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2014-11-18T00:00:00+00:00'::TIMESTAMPTZ, '0b209717568820760085d44e0452044e68f926c5644e9e58f9a7c7984c87569f'::TEXT, ARRAY[2527]::BIGINT[]),
    (283::BIGINT, 'Excelente profe, es una persona muy buena su para Intro y taller es el mejor profesor que he tenido, recomendado 100% si se quiere aprender del tema en su perfeccion'::TEXT, 4.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::BOOLEAN, NULLIF('100','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2014-11-15T00:00:00+00:00'::TIMESTAMPTZ, '920c41a5eb9160267aeb7aaaa7ad85e3eea7b5e04d6a7a3da747ee055205ddbf'::TEXT, ARRAY[2510, 2512]::BIGINT[]),
    (283::BIGINT, 'El mejor profe que he tenido.. muy bueno, todo lo explica super claro.'::TEXT, 6.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::BOOLEAN, NULLIF('100','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2014-11-15T00:00:00+00:00'::TIMESTAMPTZ, '2832d37888d61e9dc0fcbcbbf7ab1d610c816ecaea52ea3f0c898675e96e49dc'::TEXT, ARRAY[2527]::BIGINT[]),
    (283::BIGINT, 'Uno de los profesores que de verdad se preocupa que el estudiante aprenda. El conocimiento que posee es muy amplio.'::TEXT, 6.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::BOOLEAN, NULLIF('100','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2014-11-15T00:00:00+00:00'::TIMESTAMPTZ, 'cf9d4c6c9b5822893a041f4535dbe268a5a3c9ac261dd6de3d2a9acf1a6e1fea'::TEXT, ARRAY[2535]::BIGINT[]),
    (283::BIGINT, 'Es uno de los mejores profes que hay en la escuela, se preocupa por que uno entienda, explica muy bien, excelente para los cursos introductorios, tiene vocación de profesor, eso si, las progras son un poco más duras que los demás profes que dan el mismo curso, pero vale la pena'::TEXT, 4.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::BOOLEAN, NULLIF('100','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2014-11-14T00:00:00+00:00'::TIMESTAMPTZ, '8d3c2b98660df42c850fc4b0c9e3ee7a0f72247ad8784b9b9a2923e081a657c1'::TEXT, ARRAY[2510, 2512]::BIGINT[]),
    (283::BIGINT, 'Excelente profesor'::TEXT, 6.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::BOOLEAN, NULLIF('100','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2014-11-14T00:00:00+00:00'::TIMESTAMPTZ, '0bc53ca194e0fa4a9f49ccbc1f0f8507051bfa77a54fabfe8eedf07dc596b6ae'::TEXT, ARRAY[2510]::BIGINT[]),
    (283::BIGINT, 'Excelente profe, el ejemplo de cuando alguien tiene vocación de profesor y le gusta hacer que la gente aprenda.'::TEXT, 8.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::BOOLEAN, NULLIF('85','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2014-11-14T00:00:00+00:00'::TIMESTAMPTZ, '0c5234e469e46aa77db1923c7a6c0584a5a28094fcb512f9c7df7009dad69e4c'::TEXT, ARRAY[2510, 2512]::BIGINT[]),
    (283::BIGINT, 'Es un excelente profesor procura que en clase siempre se entienda todo además deja practicas que complementan perfectamente con lo teorico'::TEXT, 6.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::BOOLEAN, NULLIF('100','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2014-11-14T00:00:00+00:00'::TIMESTAMPTZ, '151c26daec01dcdd19cb97cd07af071e198158d66638de55d6d637e3fbdbf44f'::TEXT, ARRAY[2527]::BIGINT[])
), inserted_review AS (
  INSERT INTO public.professor_review (
    professor_id, comment, ease_score, quality_score, clarity_score, fairness_score,
    attendance_required, grade_received, engagement_level, tags, status, reviewed_at, created_at, updated_at, import_key
  )
  SELECT 
    professor_id, comment, ease_score, quality_score, clarity_score, fairness_score,
    attendance_required, grade_received, engagement_level, tags, 'approved'::public.professor_review_status, now(), created_at, created_at, import_key
  FROM review_input ri
  WHERE NOT EXISTS (
    SELECT 1 FROM public.professor_review pr WHERE pr.import_key = ri.import_key
  )
  RETURNING id, import_key
), target_review AS (
  SELECT id, import_key FROM inserted_review
  UNION ALL
  SELECT pr.id, pr.import_key
  FROM public.professor_review pr
  JOIN review_input ri ON ri.import_key = pr.import_key
)
INSERT INTO public.professor_review_course (review_id, course_id)
SELECT tr.id, course_id
FROM target_review tr
JOIN review_input ri ON ri.import_key = tr.import_key
CROSS JOIN LATERAL unnest(ri.course_ids) AS course_id
ON CONFLICT DO NOTHING;

COMMIT;
